using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows.Forms;using System.Windows.Media.Media3D;

namespace GearLab {

 public static class ConnectedRobotTests {

  static int checks;static void Check(bool value,string text){checks++;if(!value)throw new Exception(text);}static void Wait(Func<bool> ready,string text,int seconds=240){var watch=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&watch.Elapsed.TotalSeconds<seconds){Application.DoEvents();Thread.Sleep(20);}Check(ready(),text);}static T Get<T>(Task<T> task){Wait(()=>task.IsCompleted,"worker completion");return task.GetAwaiter().GetResult();}

  static bool WebComplete(RobotDesignerForm robot,int count){var task=robot.WebScene.Inspect();var watch=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&watch.Elapsed.TotalSeconds<3){Application.DoEvents();Thread.Sleep(10);}if(!task.IsCompleted)return false;string json=CADDocument.Serializer().Deserialize<string>(task.GetAwaiter().GetResult());var data=CADDocument.Serializer().DeserializeObject(json) as Dictionary<string,object>;return Convert.ToInt32(data["parts"])==count&&Convert.ToInt32(data["triangles"])>1000;}

  static void Detail(RobotDesignerForm robot,string path,int index,double phase){var fk=RobotKinematics.Evaluate(robot.Document,phase,true);var p=fk[robot.Document.Joints[index].Id];var center=new Point3D((p.Origin.X+p.Tip.X)/2,(p.Origin.Y+p.Tip.Y)/2,(p.Origin.Z+p.Tip.Z)/2);robot.WebScene.Send(new{type="poses",parts=robot.Build.Entries.Values.Where(e=>!e.Guide).Select(e=>new{id=e.Id,matrix=RobotWebViewport.Matrix(robot.Build.Pose(e.Id,phase,true))}).ToArray()});robot.WebScene.Send(new{type="camera",position=new[]{center.X+400,center.Y-400,center.Z+180},target=new[]{center.X,center.Y,center.Z},width=index==0?320:300});var until=DateTime.UtcNow.AddMilliseconds(350);Wait(()=>DateTime.UtcNow>until,"joint close-up camera applied",5);var shot=robot.WebScene.SavePreview(path);Wait(()=>shot.IsCompleted,"joint close-up capture");shot.GetAwaiter().GetResult();}

  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{string project=Path.Combine(folder,"SixAxis_Connected.robot.json");var doc=File.Exists(project)?RobotDocument.Parse(File.ReadAllText(project)):RobotDocument.EnclosedExample();Check(doc.Joints.Count==6,"six driven axes in reference skeleton");using(var kernel=new CADKernel()){foreach(var joint in doc.Ordered().AsEnumerable().Reverse()){File.AppendAllText(Path.Combine(folder,"progress.txt"),joint.Name+"\r\n",Encoding.UTF8);File.WriteAllText(Path.Combine(folder,"spec-"+joint.Id+".json"),CADDocument.Serializer().Serialize(ProceduralBodySpec.Build(doc,joint,joint.BodyGenerator)),Encoding.UTF8);if(joint.GeneratedBody==null||joint.GeneratedBody.Fingerprint!=ProceduralBodySpec.Fingerprint(doc,joint,joint.BodyGenerator))joint.GeneratedBody=Get(Task.Factory.StartNew(()=>ProceduralBodySpec.Generate(kernel,doc,joint,joint.BodyGenerator)));var report=joint.GeneratedBody.Result;Check(report.GeometryValid,joint.Name+": "+string.Join("; ",report.Issues.Where(i=>i.Status=="error").Select(i=>i.Message)));Check(report.Issues.Any(i=>i.Code=="cover_enclosure"&&i.Status=="pass"),joint.Name+": structural web stays inside closed housing envelope");Check(report.Issues.Any(i=>i.Code=="shell_continuity"&&i.Status=="pass"),joint.Name+": unsplit housing has no disconnected shell fragments");Check(report.Issues.Any(i=>i.Code==(joint.BodyGenerator.ReferenceDesign&&doc.Joints.Any(x=>x.ParentId==joint.Id)?"monocoque_structure":"axis_tangency")&&i.Status=="pass"),joint.Name+": native selected housing topology");if(joint.BodyGenerator.ReferenceDesign&&doc.Joints.Any(x=>x.ParentId==joint.Id))Check(report.Issues.Any(i=>i.Code=="inset_panel"&&i.Status=="pass"),joint.Name+": actual recessed panel, not recolored tube");Check(report.Mates!=null&&report.Mates.All(m=>m.BoresVerified),joint.Name+": all native mating bores exist");Check(report.Parts.Any(p=>p.Id=="output_flange")&&report.Parts.Any(p=>p.Id=="frame_0"),joint.Name+": explicit output and structural connector");log.AppendLine(joint.Name+": "+report.Parts.Count+" parts, "+report.Seconds+" sec, "+report.MassKg+" kg");doc.Save(Path.Combine(folder,"SixAxis_Connected.robot.json"));}

    var build=RobotCad.Build(doc);Check(build.Model.Valid,"assembled reference: "+string.Join(";",build.Model.Errors));Check(RobotConnections.Validate(build).Count==0,"all world mating frames and bolt patterns coincide");var contactParts=build.Entries.Values.Where(x=>!x.Guide&&x.Category!="Крепёж"&&x.Category!="Проводка").Select(x=>new{Id=x.Id,Step=CADNativeBridge.FromLegacyPart(x.Part).Features[0].Data,Transform=CADNativeBridge.Transform(build.Pose(x.Id,0,false)),Integral=x.Category=="Мотор"?x.JointId+"_motor_integral":null}).ToArray();var contacts=kernel.Run(new CADDocument(),"assembly_contacts",null,null,null,new Dictionary<string,object>{{"Spec",new{Parts=contactParts}}}).Motion;File.WriteAllText(Path.Combine(folder,"contacts.json"),CADDocument.Serializer().Serialize(contacts),Encoding.UTF8);Check(contacts.Status=="clear","assembled CAD intersections: "+string.Join("; ",contacts.Collisions.Select(c=>c.A+" / "+c.B+" "+c.Volume)));var random=new Random(51);var initial=doc.Joints.Select(j=>j.Position).ToArray();for(int pose=0;pose<32;pose++){foreach(var joint in doc.Joints)joint.Position=joint.Minimum+(joint.Maximum-joint.Minimum)*random.NextDouble();build.InvalidatePose();Check(RobotConnections.Validate(build).Count==0,"all connection frames retained in independent pose "+pose);}for(int i=0;i<6;i++)doc.Joints[i].Position=initial[i];build.InvalidatePose();

    for(int tick=0;tick<16;tick++)Check(RobotConnections.Validate(build,tick*.8,true).Count==0,"native interface frames stay joined during animated pose "+tick);build.InvalidatePose();

    var selected=doc.Joints[1];var e=build.Entries[selected.Id+"_proc_frame_0"];var original=e.Local;e.Local=RobotMath.Translation(0,0,4)*e.Local;build.InvalidatePose();Check(RobotConnections.Validate(build).Count>0,"actual displacement of structural member is rejected");e.Local=original;build.InvalidatePose();

    var changed=doc.Clone();changed.Joints[1].EndZ+=40;var parent=changed.Joints[1];var pending=RobotCad.Build(changed);Check(pending.Model.Valid,"a dimension edit can wait for regeneration without stale mating errors");bool staleBlocked=false;try{pending.ForExport(false,null);}catch(Exception){staleBlocked=true;}Check(staleBlocked,"stale native housing cannot be exported during regeneration");var childPortBefore=parent.GeneratedBody.Result.Mates.First(m=>m.Id=="link_child");parent.GeneratedBody=Get(Task.Factory.StartNew(()=>ProceduralBodySpec.Generate(kernel,changed,parent,parent.BodyGenerator)));Check(parent.GeneratedBody.Result.GeometryValid,"resized member remains connected native geometry");var after=RobotCad.Build(changed);Check(after.Model.Valid&&RobotConnections.Validate(after).Count==0,"length edit relocates actual child mating flange without detaching it");

    PrintExport.Zip(build.ForExport(true,null),Path.Combine(folder,"SixAxis_print.zip"));Check(new FileInfo(Path.Combine(folder,"SixAxis_print.zip")).Length>1000,"native closed housings export as individually oriented STL parts");StepExport.Write(build.ForExport(false,null),Path.Combine(folder,"SixAxis_assembly.step"));doc.Save(Path.Combine(folder,"SixAxis_Connected.robot.json"));Check(RobotDocument.Parse(doc.Serialize()).Joints.Count==6,"six-axis native project roundtrip");

   }

   using(var robot=new RobotDesignerForm())using(var shell=new WorkspaceShell(robot)){robot.SetDocument(doc);shell.Show();Wait(()=>robot.WebScene.Ready&&robot.Scene.Ready,"six-axis native viewport");Wait(()=>WebComplete(robot,robot.Build.Entries.Values.Count(e=>!e.Guide)),"all native meshes visible before capture",60);var clean=CADDocument.Serializer().DeserializeObject(CADDocument.Serializer().Deserialize<string>(Get(robot.WebScene.Inspect()))) as Dictionary<string,object>;Check(Convert.ToInt32(clean["bones"])==0,"body mode hides skeleton guides");var snapshot=robot.WebScene.SavePreview(Path.Combine(folder,"six-axis.png"));Wait(()=>snapshot.IsCompleted,"viewport capture");snapshot.GetAwaiter().GetResult();Detail(robot,Path.Combine(folder,"joint-base.png"),0,0);Detail(robot,Path.Combine(folder,"joint-wrist.png"),4,3.2);shell.Navigate("reducer");var reducers=shell.Pages.SelectedTab.Tag as ReducerWorkspaceForm;Check(reducers!=null,"one unified reducer workspace");reducers.SelectWave();reducers.MainView.ShowFullModel();Wait(()=>reducers.MainView!=null&&reducers.MainView.CurrentParameters.Kind==4&&reducers.MainView.SceneReady,"harmonic reducer builds inside reducer section",240);Check(shell.Pages.TabCount==2,"harmonic selection adds no independent workspace tab");reducers.SelectOrdinary();Application.DoEvents();Check(reducers.MainView.CurrentParameters.Kind==0,"ordinary family reuses common editor");shell.Navigate("robot");Check(!reducers.Visible&&robot.Visible,"old reducer scene hidden when switching sections");shell.ApproveTestClose();shell.Close();}

   File.WriteAllText(Path.Combine(folder,"connected-results.txt"),"PASS "+checks+" assertions\r\n"+log,Encoding.UTF8);return 0;

  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"connected-error.txt"),log+"\r\n"+ex,Encoding.UTF8);return 1;}}

 }

}

